    // box (`app.css`, `.hero-net`), so the two spaces no longer coincide.
    left -= this.canvas.offsetLeft
    top -= this.canvas.offsetTop
    this.card = { left, top, width: this.cardEl.offsetWidth, height: this.cardEl.offsetHeight }
