import { expect, test } from 'bun:test'

import {
  consoleEntry,
  cloudFade,
  ENTRY_MS,
  ENTRY_REVEAL,
  energyParticle,
  entryDelay,
  entrySpan,
  markTransform,
  phaseAt,
  PHASES,
} from '../src/lib/motion/entry'
import { markPolygons, markSpin } from '../src/lib/motion/mark'

/**
 * The entry choreography (spec 31): six overlapping phases over 4.2 seconds, expressed as
 * fractions of the duration so one constant retimes all of it. Everything here is pure —
 * `entryDriver.ts` owns the canvas — which is what lets these tests pin the landing down
 * to the last bit, and the landing is the part that has to be exact.
 */

const D = ENTRY_MS
const VIEW = { w: 1440, h: 900 }
const NAV = { x: 42, y: 32, box: 20 }

test('the phase table is ordered and every pair of neighbors overlaps', () => {
  expect(PHASES.map((phase) => phase.name)).toEqual([
    'SEED',
    'EXPAND',
    'DOCK',
    'ENERGY',
    'CONSOLE',
    'CONTENT',
  ])

  PHASES.forEach((phase, i) => {
    expect(phase.from).toBeLessThan(phase.to)
    const next = PHASES[i + 1]
    if (!next) return
    expect(phase.from).toBeLessThan(next.from)
    // The overlap is the design: sequential phases came to 7.2s in the prototype.
    expect(phase.to).toBeGreaterThan(next.from)
  })

  expect(PHASES[0]!.from).toBe(0)
  expect(PHASES[PHASES.length - 1]!.to).toBe(1)
})

test('entrySpan scales linearly with the duration', () => {
  for (const phase of PHASES) {
    const single = entrySpan(phase.name, D)
    const double = entrySpan(phase.name, D * 2)
    expect(double.from).toBeCloseTo(single.from * 2, 10)
    expect(double.to).toBeCloseTo(single.to * 2, 10)
    expect(single.from).toBeCloseTo(phase.from * D, 10)
    expect(single.to).toBeCloseTo(phase.to * D, 10)
  }
})

test('phaseAt is 0 before its phase, 1 after it, and rises in between', () => {
  const { from, to } = entrySpan('DOCK', D)

  expect(phaseAt('DOCK', 0, D)).toBe(0)
  expect(phaseAt('DOCK', from, D)).toBe(0)
  expect(phaseAt('DOCK', to, D)).toBe(1)
  expect(phaseAt('DOCK', D, D)).toBe(1)
  expect(phaseAt('DOCK', (from + to) / 2, D)).toBeCloseTo(0.5, 10)

  let previous = -1
  for (let t = 0; t <= D; t += 20) {
    const p = phaseAt('DOCK', t, D)
    expect(p).toBeGreaterThanOrEqual(previous)
    previous = p
  }
})

test('markTransform starts collapsed at the center of the viewport', () => {
  const frame = markTransform(0, D, VIEW, NAV)

  expect(frame.expand).toBeCloseTo(0.08, 12)
  expect(frame.settle).toBe(0)
  expect(frame.center.x).toBeCloseTo(VIEW.w / 2, 12)
  expect(frame.center.y).toBeCloseTo(VIEW.h * 0.43, 12)
  // A point of light: a quarter of the settled size, at a third of its opacity.
  expect(frame.scale).toBeCloseTo(Math.min(VIEW.w, VIEW.h) * 0.19 * 0.85 * 0.25, 12)
  expect(frame.alpha).toBeCloseTo(0.35, 12)
})

test('markTransform lands on the nav slot', () => {
  const frame = markTransform(D, D, VIEW, NAV)

  expect(frame.expand).toBe(1)
  expect(frame.settle).toBe(1)
  expect(frame.alpha).toBe(1)
  expect(Math.abs(frame.center.x - NAV.x)).toBeLessThan(1e-9)
  expect(Math.abs(frame.center.y - NAV.y)).toBeLessThan(1e-9)
  expect(frame.scale).toBe(NAV.box)
})

test("the overlay's last frame is the nav canvas' frame", () => {
  // The defect this pins down survived fourteen commits in spec 30: an overlay that lands
  // one bit away from what `markDraw.ts` paints makes the mark jump the moment the overlay
  // is destroyed. Deep equality of the two arrays, not the contents of either.
  const frame = markTransform(D, D, VIEW, NAV)
  const overlay = markPolygons(frame.scale, frame.settle, D, frame.spinY, frame.expand)
  const nav = markPolygons(NAV.box, 1, D, markSpin(D))

  expect(overlay).toEqual(nav)
})

test('the cluster keeps turning through the flight and hands over in step', () => {
  // `spinY` is the mark's own idle turn plus the unwinding of the expansion, so at the end
  // of EXPAND it is exactly what the nav canvas would be showing at the same clock.
  const early = markTransform(0, D, VIEW, NAV)
  expect(early.spinY).toBeCloseTo(markSpin(0) + 2.4, 12)

  const settled = entrySpan('EXPAND', D).to
  expect(markTransform(settled, D, VIEW, NAV).spinY).toBeCloseTo(markSpin(settled), 12)
})

test('entryDelay is monotonic and the last reveal finishes inside the entry tail', () => {
  const delays = [0, 1, 2, 3, 4].map((n) => entryDelay(n, D))

  expect(delays).toEqual([...delays].sort((a, b) => a - b))
  expect(new Set(delays).size).toBe(delays.length)
  expect(delays[0]).toBeCloseTo(entrySpan('CONTENT', D).from, 10)
  expect(delays[4]! + ENTRY_REVEAL * D).toBeLessThanOrEqual(D + ENTRY_REVEAL * D)
  // Doubling the duration doubles the cascade with it, like every other span.
  expect(entryDelay(4, D * 2)).toBeCloseTo(entryDelay(4, D) * 2, 10)
})

test('energyParticle leaves the mark and lands on its node', () => {
  const from = { x: 60, y: 40 }
  const to = { x: 980, y: 520 }

  expect(energyParticle(from, to, 0, 0, VIEW.h)).toEqual(from)
  expect(energyParticle(from, to, 1, 0, VIEW.h)).toEqual(to)
  // Staggered particles still land: the delay only shortens the flight, it never clips it.
  expect(energyParticle(from, to, 1, 0.9, VIEW.h)).toEqual(to)
  expect(energyParticle(from, to, 0.2, 0.9, VIEW.h)).toEqual(from)

  for (let i = 0; i <= 200; i++) {
    const p = energyParticle(from, to, i / 200, 0.3, VIEW.h)
    expect(p.y).toBeGreaterThanOrEqual(0)
    expect(p.y).toBeLessThanOrEqual(VIEW.h)
    expect(p.x).toBeGreaterThanOrEqual(Math.min(from.x, to.x))
    expect(p.x).toBeLessThanOrEqual(Math.max(from.x, to.x))
  }

  // The arc: the particle falls out of the mark instead of sliding toward the cloud.
  const mid = energyParticle(from, to, 0.6, 0, VIEW.h)
  expect(mid.y).toBeLessThan(from.y + (to.y - from.y) * 0.6)
})

test('consoleEntry holds the card until its phase and sweeps once inside it', () => {
  const { from, to } = entrySpan('CONSOLE', D)

  expect(consoleEntry(0, D)).toEqual({
    opacity: 0,
    translateY: 24,
    scale: 0.96,
    blur: 10,
    sweep: 0,
  })
  expect(consoleEntry(from, D).opacity).toBe(0)
  expect(consoleEntry(to, D)).toEqual({
    opacity: 1,
    translateY: 0,
    scale: 1,
    blur: 0,
    sweep: 1,
  })
  expect(consoleEntry(D, D).opacity).toBe(1)

  const sweepFrom = from + 0.35 * (to - from)
  expect(consoleEntry(sweepFrom, D).sweep).toBe(0)
  for (let t = sweepFrom + 1; t < to; t += 5) {
    const sweep = consoleEntry(t, D).sweep
    expect(sweep).toBeGreaterThan(0)
    expect(sweep).toBeLessThan(1)
  }
  expect(consoleEntry(D, D).sweep).toBe(1)
})

test('cloudFade brings the real cloud up over the energy phase', () => {
  const { from, to } = entrySpan('ENERGY', D)

  expect(cloudFade(0, D)).toBe(0)
  expect(cloudFade(from, D)).toBe(0)
  expect(cloudFade(to, D)).toBe(1)
  expect(cloudFade(D, D)).toBe(1)
  expect(cloudFade((from + to) / 2, D)).toBeGreaterThan(0.5)
})

import { markSpin } from './mark'
import { lerp, type Point } from './math'

// ── The entry choreography (spec 31) ─────────────────────────────────────────
// Six overlapping phases: the mark seeds at the center of the viewport, expands into its
// lattice, flies into the nav, throws energy into the hero that becomes the node cloud,
// the console rises with its scan line, and the hero copy cascades last. Everything here
// is pure, so `bun test` reaches all of it; `entryDriver.ts` owns the canvas.
//
// This replaces `MOTION_SPEC` §2's boot timing and §3's ✳ formation. `handoff/` is
// read-only and still describes both; spec 31 documents the deviation.

export type PhaseName = 'SEED' | 'EXPAND' | 'DOCK' | 'ENERGY' | 'CONSOLE' | 'CONTENT'

export type Phase = { name: PhaseName; from: number; to: number }

/**
 * Fractions of the total duration, so one constant retimes the whole sequence. The phases
 * overlap on purpose: run end to end they came to 7.2s in the prototype, which is too long
 * for a first visit. Energy leaves the mark while it is still in flight, and the console
 * arrives while the cloud is still assembling.
 */
export const PHASES: readonly Phase[] = [
  { name: 'SEED', from: 0, to: 0.095 },
  { name: 'EXPAND', from: 0.09, to: 0.38 },
  { name: 'DOCK', from: 0.355, to: 0.57 },
  { name: 'ENERGY', from: 0.52, to: 0.76 },
  { name: 'CONSOLE', from: 0.69, to: 0.88 },
  { name: 'CONTENT', from: 0.78, to: 1 },
]

/** Below 3200 the expansion stops reading; above 5000 the site feels like it waits. */
export const ENTRY_MS = 4200

/** How long one `[data-boot]` element takes to arrive, as a fraction of the duration. */
export const ENTRY_REVEAL = 0.09

const clamp01 = (value: number) => Math.min(1, Math.max(0, value))
const norm = (t: number, a: number, b: number) => clamp01((t - a) / (b - a))
const inOut = (t: number) => (t < 0.5 ? 4 * t ** 3 : 1 - (-2 * t + 2) ** 3 / 2)
const outCubic = (t: number) => 1 - (1 - t) ** 3
const outBack = (t: number) => 1 + 2.70158 * (t - 1) ** 3 + 1.70158 * (t - 1) ** 2

const phase = (name: PhaseName): Phase => PHASES.find((p) => p.name === name) as Phase

/** The bounds of one phase in milliseconds, at a total duration of `D`. */
export function entrySpan(name: PhaseName, D: number): { from: number; to: number } {
  const { from, to } = phase(name)
  return { from: from * D, to: to * D }
}

/** Progress of one phase in [0, 1] at `t`: 0 before it starts, 1 once it has ended. */
export function phaseAt(name: PhaseName, t: number, D: number): number {
  const { from, to } = entrySpan(name, D)
  return norm(t, from, to)
}

export type MarkFrame = {
  /** How far the pieces have flown out of the seed, in `markPolygons` units. */
  expand: number
  /** 0 while the pieces are still unwinding their turns, 1 at rest. */
  settle: number
  /** The turn of the whole cluster, the mark's own idle spin included. */
  spinY: number
  center: Point
  /** Side of the square `markPolygons` draws into, in CSS pixels. */
  scale: number
  alpha: number
}

/**
 * The mark at `t`: collapsed at the center of the viewport, expanding into the lattice,
 * then shrinking into the nav slot. `nav` is the FLIP target — the center and the box of
 * the nav's `[data-mark]`, measured once by the driver.
 *
 * The landing is a clamp and not a lerp on purpose. At `dock = 1` the overlay's frame has
 * to be *the same* frame `markDraw.ts` paints in the nav, and `a + (b - a) * 1` is not
 * always `b` in IEEE-754: one ulp of difference in the box is a visible jump the moment the
 * overlay is destroyed.
 */
export function markTransform(
  t: number,
  D: number,
  view: { w: number; h: number },
  nav: { x: number; y: number; box: number },
): MarkFrame {
  const pSeed = phaseAt('SEED', t, D)
  const pExpand = phaseAt('EXPAND', t, D)
  const pDock = phaseAt('DOCK', t, D)
  const dock = inOut(pDock)
  const landed = dock >= 1

  // The pieces overshoot slightly and settle; the cluster's growth is a plain outCubic.
  const expand = pExpand >= 1 ? 1 : lerp(0.08, 1, outBack(pExpand))
  const big = Math.min(view.w, view.h) * 0.19 * 0.85
  const grown = big * lerp(0.25, 1, outCubic(pExpand))

  return {
    expand,
    settle: outCubic(clamp01((pExpand - 0.25) / 0.75)),
    // Whole extra turns while the pieces are still out: the cluster arrives already
    // turning, and by the end of EXPAND it is exactly on the mark's own idle spin.
    spinY: markSpin(t) + (1 - pExpand) * 2.4,
    center: landed
      ? { x: nav.x, y: nav.y }
      : { x: lerp(view.w / 2, nav.x, dock), y: lerp(view.h * 0.43, nav.y, dock) },
    scale: landed ? nav.box : lerp(grown, nav.box, dock),
    alpha: lerp(0.35, 1, clamp01(pSeed * 2)),
  }
}

/**
 * When the element with `data-boot="n"` is revealed. Replaces `bootDelay`, which was
 * `500 + n · 170` against a fixed clock: the cascade is the last phase of the entry now,
 * so it retimes with `D` like everything else.
 */
export function entryDelay(n: number, D: number): number {
  return entrySpan('CONTENT', D).from + n * 0.038 * D
}

/**
 * One energy particle on its way from the mark to the node it becomes. `delay` in [0, 1)
 * staggers it, so the cloud fills in instead of arriving as a block, and the sine lifts it
 * onto an arc so it falls out of the mark rather than sliding toward the hero.
 *
 * The particles are decoration on the overlay: `network.ts` keeps owning the real cloud and
 * fades in over the same window (`cloudFade`), so they arrive as it resolves.
 */
export function energyParticle(
  from: Point,
  to: Point,
  pEnergy: number,
  delay: number,
  h: number,
): Point {
  const e = outCubic(clamp01((pEnergy - delay * 0.5) * 2))
  // Exactly on the node, not a rounding error away from it: the real cloud is already
  // painting there and a particle half a pixel off reads as a double node.
  if (e >= 1) return { x: to.x, y: to.y }
  const y = lerp(from.y, to.y, e) - Math.sin(e * Math.PI) * h * 0.12
  return { x: lerp(from.x, to.x, e), y: Math.min(h, Math.max(0, y)) }
}

/**
 * The console card over its phase: it rises, unblurs and takes the scan line 35% in. The
 * driver writes all five per frame, which is why the card's resting state in `app.css`
 * carries no transition of its own — a transition would fight the frames.
 */
export function consoleEntry(
  t: number,
  D: number,
): { opacity: number; translateY: number; scale: number; blur: number; sweep: number } {
  const { from, to } = entrySpan('CONSOLE', D)
  const p = outCubic(phaseAt('CONSOLE', t, D))
  return {
    opacity: p,
    translateY: (1 - p) * 24,
    scale: lerp(0.96, 1, p),
    blur: (1 - p) * 10,
    sweep: norm(t, from + 0.35 * (to - from), to),
  }
}

/** The hero cloud's own fade-in, so the particles land as the real nodes resolve. */
export function cloudFade(t: number, D: number): number {
  return outCubic(phaseAt('ENERGY', t, D))
}

