   Off the top of the viewport until it takes focus, and moved with `top` rather than a
   transform so nothing animates for a visitor who asked for no motion. */

@layer components {
  .skip-link {
    position: fixed;
    top: -100px;
    left: 12px;
    z-index: 30;
    padding: 10px 18px;
    border: 1px solid var(--color-accent);
    border-radius: 999px;
    background: var(--color-bg);
    color: var(--color-ink);
    font-size: 15px;
    font-weight: 500;
  }

  .skip-link:focus-visible {
    top: 12px;
  }
}

/* ── Aurora ───────────────────────────────────────────────────────────────────
   The site's background layer (`MOTION_SPEC §4`): three blurred blobs, fixed, the
   only thing painted at z-index 0. Decoration — `aria-hidden` in the markup, no
   pointer events, and readable without JS since it needs none to show.

   The light theme runs the blobs at roughly 40% of §4's alphas (spec 26): over a
   near-white `--color-bg` the specified 22%/14%/12% cost the footer's `--color-dim`
   and `--color-accent` their WCAG ratios, and `tests/contrast.test.ts` composites the
   worst overlap to keep it that way. The dark theme keeps §4's values, which clear it. */

@layer components {
  .aurora {
    position: fixed;
    /* The layer hangs 13vh below the viewport. `translateY(-12vh · p)` of §4 moves the
       element *and its `overflow` clip box* up, so with `inset: 0` the bottom 12vh·p of
       the viewport ends up outside the box: an untinted strip with a hard edge that
       grows as you scroll and vanishes back at the top (spec 26). 13 rather than the
       12vh of the travel because the two `vh` round independently, and at 12 the box
       lands a hundredth of a pixel short of the viewport. */
    inset: 0 0 -13vh 0;
    z-index: 0;
    overflow: hidden;
    pointer-events: none;
    /* Scroll drives filter/opacity/transform once per frame; this smooths the steps. */
    transition:
      filter 0.2s linear,
      opacity 0.2s linear;
  }

  .aurora > * {
    position: absolute;
    border-radius: 50%;
  }

  .aurora > :nth-child(1) {
    left: 55%;
    top: -10%;
    width: 56vw;
    height: 56vw;
    filter: blur(90px);
    background: light-dark(
      color-mix(in srgb, var(--color-accent) 8%, transparent),
      color-mix(in srgb, var(--color-accent) 16%, transparent)
    );
  }

  .aurora > :nth-child(2) {
    left: 20%;
    top: 30%;
    width: 44vw;
    height: 44vw;
    filter: blur(100px);
    background: light-dark(
      color-mix(in srgb, var(--color-violet) 5%, transparent),
      color-mix(in srgb, var(--color-violet) 14%, transparent)
    );
  }

  .aurora > :nth-child(3) {
    left: 70%;
    top: 40%;
    width: 36vw;
    height: 36vw;
    filter: blur(90px);
    background: light-dark(
      color-mix(in srgb, var(--color-accent) 4%, transparent),
      color-mix(in srgb, var(--color-accent) 8%, transparent)
    );
  }

  /* Two blobs on narrow viewports (`MOTION_SPEC §13`). */
  @media (width < 720px) {
    .aurora > :nth-child(3) {
      display: none;
    }
  }

  @media (prefers-reduced-motion: no-preference) {
    .aurora > :nth-child(1) {
      animation: aur1 16s ease-in-out infinite alternate;
    }

    .aurora > :nth-child(2) {
      animation: aur2 20s ease-in-out infinite alternate;
    }

    .aurora > :nth-child(3) {
      animation: aur1 24s ease-in-out infinite alternate-reverse;
    }

    /* Resting opacity of the scroll ramp. Only with JS, which raises it on the first
       frame — without JS the aurora stays at full strength instead of dimmed. */
    .has-js .aurora {
      opacity: 0.45;
    }
  }
}

/* ── Node network ─────────────────────────────────────────────────────────────
   The hero's canvas (`MOTION_SPEC §3`). Created by `motion/network.ts` and never
   server-rendered, so it exists neither without JS nor with reduced motion —
   which is also why its rule lives here instead of in a scoped component style.

   `color` and `border-color` are how the canvas learns the theme: `network.ts`
   reads them back resolved from `getComputedStyle`, so it repaints in the right
   accent when the toggle flips, and never names a color of its own. */

/* ── Entry overlay ────────────────────────────────────────────────────────────
   The canvas the entry choreography flies the mark across (spec 31). Created by
   `motion/entryDriver.ts`, removed from the DOM when the sequence ends, and never
   server-rendered — so, like `.hero-net`, its rule lives here and not in a component.

   A child of `body` rather than of the `z-[1]` wrapper: the nav is sticky at
   `z-index: 20` inside that wrapper, and the mark has to fly over it. */

@layer components {
  #entry {
    position: fixed;
    inset: 0;
    z-index: 30;
    pointer-events: none;
    color: var(--color-accent);
  }
}

@layer components {
  .hero-net {
    position: absolute;
    left: 0;
    /* `MOTION_SPEC §3` asks for a `100vw × 100vh` canvas, and the mock anchors it to the
       top of the page. The nav is `--nav-h` tall and sits in flow above the hero, so this
       lifts the canvas out of the section and onto the viewport box. It is not cosmetic:
       `ry = .48h`, the ✳ radius and the 55% cut of the mask below all divide by this
       height, and tying them to a section that re-flows is how the cloud drifts. */
    top: calc(-1 * var(--nav-h));
    z-index: 0;
    width: 100%;
    height: 100vh;
    pointer-events: none;
    color: var(--color-accent);
    border-color: var(--color-violet);
    mask-image: linear-gradient(180deg, #000 55%, transparent);
  }
}

/* ── Boot ─────────────────────────────────────────────────────────────────────
   Resting state of the boot sequence (`MOTION_SPEC §2`): hidden only when JS is
   there to reveal it and motion is welcome, so the page reads without either.
   `motion/boot.ts` clears the three properties at `bootDelay(n)`. */

