import { chromium } from 'playwright'

const browser = await chromium.launch()
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
await page.goto('file:///Users/djmaam/Projects/Marcos/portfolio-v3/docs/prototypes/logo-cube.html')
await page.waitForTimeout(800)

const probe = await page.evaluate(() => {
  const scrub = document.getElementById('scrub') as HTMLInputElement
  const stage = document.getElementById('stage')!
  const canvas = document.getElementById('cvLogo') as HTMLCanvasElement
  const rect = stage.getBoundingClientRect()

  // End of EXPAND: 0.38 of the timeline, before the dock shrinks it.
  scrub.value = String(Number(scrub.max) * 0.38)
  scrub.dispatchEvent(new Event('input', { bubbles: true }))

  return new Promise((resolve) => {
    requestAnimationFrame(() =>
      requestAnimationFrame(() => {
        const ctx = canvas.getContext('2d')!
        const px = ctx.getImageData(0, 0, canvas.width, canvas.height).data
        const dpr = canvas.width / canvas.getBoundingClientRect().width
        let minX = Infinity
        let maxX = -Infinity
        let minY = Infinity
        let maxY = -Infinity
        for (let y = 0; y < canvas.height; y++)
          for (let x = 0; x < canvas.width; x++) {
            if ((px[(y * canvas.width + x) * 4 + 3] as number) < 30) continue
            if (x < minX) minX = x
            if (x > maxX) maxX = x
            if (y < minY) minY = y
            if (y > maxY) maxY = y
          }
        resolve({
          stage: { w: rect.width, h: rect.height },
          scrubMax: scrub.max,
          inkWidth: (maxX - minX) / dpr,
          inkHeight: (maxY - minY) / dpr,
          fractionOfStageHeight: (maxY - minY) / dpr / rect.height,
          fractionOfStageWidth: (maxX - minX) / dpr / rect.width,
        })
      }),
    )
  })
})
console.log(JSON.stringify(probe, null, 1))
await browser.close()
